326  PIX *
   327  pixRemoveColormap(PIX     *pixs,
   328                    l_int32  type)
   329  {
   330  l_int32    sval, rval, gval, bval, val0, val1;
   331  l_int32    i, j, k, w, h, d, wpls, wpld, ncolors, nalloc, count;
   332  l_int32    opaque, colorfound, blackwhite;
   333  l_int32   *rmap, *gmap, *bmap, *amap;
   334  l_uint32  *datas, *lines, *datad, *lined, *lut, *graymap;
   335  l_uint32   sword, dword;
   336  PIXCMAP   *cmap;
   337  PIX       *pixd;
   338
   339      PROCNAME("pixRemoveColormap");
   340
   341      if (!pixs)
   342          return (PIX *)ERROR_PTR("pixs not defined", procName, NULL);
   343      if ((cmap = pixGetColormap(pixs)) == NULL)
   344          return pixClone(pixs);
   345      if (type != REMOVE_CMAP_TO_BINARY &&
   346          type != REMOVE_CMAP_TO_GRAYSCALE &&
   347          type != REMOVE_CMAP_TO_FULL_COLOR &&
   348          type != REMOVE_CMAP_WITH_ALPHA &&
   349          type != REMOVE_CMAP_BASED_ON_SRC) {
   350          L_WARNING("Invalid type; converting based on src\n", procName);
   351          type = REMOVE_CMAP_BASED_ON_SRC;
   352      }
   353      pixGetDimensions(pixs, &w, &h, &d);
   354      if (d != 1 && d != 2 && d != 4 && d != 8)
   355          return (PIX *)ERROR_PTR("pixs must be {1,2,4,8} bpp", procName, NULL);
   356
   357      ncolors = pixcmapGetCount(cmap);
   358      nalloc = 1 << d;  /* allocate for max size in case of pixel corruption */
   359      if (ncolors > nalloc)
   360          return (PIX *)ERROR_PTR("too many colors for pixel depth",
   361                                  procName, NULL);
   362
   363      if (pixcmapToArrays(cmap, &rmap, &gmap, &bmap, &amap))
   364          return (PIX *)ERROR_PTR("colormap arrays not made", procName, NULL);
   365
   366      if (d != 1 && type == REMOVE_CMAP_TO_BINARY) {
   367          L_WARNING("not 1 bpp; can't remove cmap to binary\n", procName);
   368          type = REMOVE_CMAP_BASED_ON_SRC;
   369      }
   370
   371          /* Select output type depending on colormap content */
   372      if (type == REMOVE_CMAP_BASED_ON_SRC) {
   373          pixcmapIsOpaque(cmap, &opaque);
   374          pixcmapHasColor(cmap, &colorfound);
   375          pixcmapIsBlackAndWhite(cmap, &blackwhite);
   376          if (!opaque) {  /* save the alpha */
   377              type = REMOVE_CMAP_WITH_ALPHA;
   378          } else if (colorfound) {
   379              type = REMOVE_CMAP_TO_FULL_COLOR;
   380          } else {  /* opaque and no color */
   381              if (d == 1 && blackwhite)  /* can binarize without loss */
   382                  type = REMOVE_CMAP_TO_BINARY;
   383              else
   384                  type = REMOVE_CMAP_TO_GRAYSCALE;
   385          }
   386      }
   387
   388      datas = pixGetData(pixs);
   389      wpls = pixGetWpl(pixs);
   390      if (type == REMOVE_CMAP_TO_BINARY) {
   391          if ((pixd = pixCopy(NULL, pixs)) == NULL) {
   392              L_ERROR("pixd not made\n", procName);
   393              goto cleanup_arrays;
   394          }
   395          pixcmapGetColor(cmap, 0, &rval, &gval, &bval);
   396          val0 = rval + gval + bval;
   397          pixcmapGetColor(cmap, 1, &rval, &gval, &bval);
   398          val1 = rval + gval + bval;
   399          if (val0 < val1)  /* photometrically inverted from standard */
   400              pixInvert(pixd, pixd);
   401          pixDestroyColormap(pixd);
   402      } else if (type == REMOVE_CMAP_TO_GRAYSCALE) {
   403          if ((pixd = pixCreate(w, h, 8)) == NULL) {
   404              L_ERROR("pixd not made\n", procName);
   405              goto cleanup_arrays;
   406          }
   407          pixCopyResolution(pixd, pixs);
   408          pixCopyInputFormat(pixd, pixs);
   409          datad = pixGetData(pixd);
   410          wpld = pixGetWpl(pixd);
   773  /*!
   774   * \brief   pixCopyColormap()
   775   *
   776   * \param[in]   pixd
   777   * \param[in]   pixs   copies the colormap to %pixd
   778   * \return  0 if OK, 1 on error
   779   *
   780   * <pre>
   781   * Notes:
   782   *      (1) This destroys the colormap in pixd, unless the operation is a no-op
   783   * </pre>
   784   */
   785  l_ok
   786  pixCopyColormap(PIX        *pixd,
   787                  const PIX  *pixs)
   788  {
   789  l_int32         valid;
   790  const PIXCMAP  *cmaps;
   791  PIXCMAP        *cmapd;
   792
   793      PROCNAME("pixCopyColormap");
   794
   795      if (!pixs)
   796          return ERROR_INT("pixs not defined", procName, 1);
   797      if (!pixd)
   798          return ERROR_INT("pixd not defined", procName, 1);
   799      if (pixs == pixd)
   800          return 0;   /* no-op */
   801
   802      pixDestroyColormap(pixd);
   803      if ((cmaps = pixs->colormap) == NULL)  /* not an error */
   804          return 0;
   805      pixcmapIsValid(cmaps, &valid);
   806      if (!valid)
   807          return ERROR_INT("cmap not valid", procName, 1);
   808
   809      if ((cmapd = pixcmapCopy(cmaps)) == NULL)
   810          return ERROR_INT("cmapd not made", procName, 1);
   811      pixSetColormap(pixd, cmapd);
   812      return 0;
   813  }
